//! Cargo-driven `psapi.dll` link, generated by tools/cargo_cell_gen.py
//! from the cmake link it replaces.
//! The body is psapi-rust; reactos-link builds the PE.

use reactos_link::{Linker, ModuleKind};
use std::env;

fn main() {
    let arch = env::var("CARGO_CFG_TARGET_ARCH").expect("CARGO_CFG_TARGET_ARCH");
    let (target_json, entry, image_base) = match arch.as_str() {
        "x86" => ("i686-pc-windows-gnu", "_DllMain@12", Some(0x79860000u64)),
        "x86_64" => ("x86_64-pc-windows-gnu", "DllMain", Some(0x7ff9b000000u64)),
        "aarch64" => ("aarch64-pc-windows-gnullvm", "DllMain", Some(0x7ff9b000000u64)),
        o => panic!("psapi-cargo: unsupported arch {o}"),
    };

    let link_order: &[&str] = match arch.as_str() {
        "x86" => &["body", "engine:pseh", "import:kernel32", "import:ntdll", "engine:chkstk"],
        "x86_64" => &["body", "engine:pseh", "import:kernel32", "import:ntdll"],
        "aarch64" => &["body", "engine:pseh", "import:kernel32", "import:ntdll", "engine:chkstk"],
        _ => unreachable!(),
    };

    // The module's part of cmake's windres command; reactos-link adds what every
    // module shares from reactos-link/cflags/rc.<arch>.flags (Linker::rc).
    let rc_includes: &[&str] = &[
        "@build/dll/win32/psapi",
        "dll/win32/psapi",
        "@std",
        "vendor/opengl-headers/include",
        "vendor/libdxg/include",
        "sdk/lib/pseh/include",
    ];
    let rc_flags: &[&str] = &[];
    let rc_defines: &[&str] = &["WINVER=0x502", "_WIN32_WINNT=0x502"];

    Linker::new(target_json)
        .rust_lib("psapi-rust", &["dllmain"], true)
        .rc("dll/win32/psapi/psapi.rc", rc_includes, rc_flags, rc_defines)
        .spec2def("dll/win32/psapi/psapi.spec", "psapi.dll")
        .import_lib("dll/win32/kernel32/kernel32.spec", "kernel32.dll", "kernel32")
        .import_lib("dll/ntdll/def/ntdll.spec", "ntdll.dll", "ntdll")
        // The body, import libs and static libs in cmake's link order: the first
        // to define a symbol wins. cmake-built ones are reused until each has a
        // cargo home; `engine:` ones reactos-link builds.
        .link_order(link_order)
        .link(ModuleKind::Win32Dll {
            entry: entry.into(),
            image_base,
            subsystem: None,
        });
}
